"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7441],{37211:e=>{e.exports=JSON.parse('{"functions":[{"name":"name","desc":"","params":[{"name":"settings","desc":"","lua_type":"any"},{"name":"partition","desc":"","lua_type":"string"},{"name":"count","desc":"","lua_type":"number"},{"name":"lane","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"string\\n"}],"function_type":"static","source":{"line":56,"path":"src/internal/Lanes.luau"}},{"name":"laneFor","desc":"Which lane a ticket belongs to at a given count. Deterministic across\\nservers, so two servers on the same count always agree.","params":[{"name":"count","desc":"","lua_type":"number"},{"name":"ticketId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":67,"path":"src/internal/Lanes.luau"}},{"name":"legacyMaps","desc":"The maps from `previous` that could hold tickets whose lane, at `count`, is\\n`lane`.\\n\\nOnly [LaneScaler] resizes, and it only ever doubles or halves from one, so\\nboth counts here are always powers of two. That is what makes this exact\\nrather than approximate. A ticket hashes to `h % count`:\\n\\n- **Growing** (`count > previous`): a ticket in old map `o` satisfies\\n  `h % previous == o`, so its new lane is one of `o`, `o + previous`,\\n  `o + 2*previous`, \u2026 Reading old map `lane % previous` therefore covers it.\\n- **Shrinking** (`count < previous`): `h % count == (h % previous) % count`,\\n  so every old map `o` with `o % count == lane` contributes.\\n\\nEither way the result holds at most `previous / count` entries \u2014 one when\\ngrowing, two on a single halving.","params":[{"name":"settings","desc":"","lua_type":"any"},{"name":"partition","desc":"","lua_type":"string"},{"name":"count","desc":"","lua_type":"number"},{"name":"lane","desc":"","lua_type":"number"},{"name":"previous","desc":"","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"{ string }\\n"}],"function_type":"static","source":{"line":93,"path":"src/internal/Lanes.luau"}},{"name":"descriptor","desc":"","params":[{"name":"settings","desc":"","lua_type":"any"},{"name":"partition","desc":"","lua_type":"string"},{"name":"count","desc":"","lua_type":"number"},{"name":"lane","desc":"","lua_type":"number"},{"name":"previous","desc":"The count being drained, if one still is.","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"Descriptor\\n"}],"function_type":"static","source":{"line":113,"path":"src/internal/Lanes.luau"}},{"name":"forTicket","desc":"The lane descriptor a given ticket lands in at `count`.","params":[{"name":"settings","desc":"","lua_type":"any"},{"name":"partition","desc":"","lua_type":"string"},{"name":"count","desc":"","lua_type":"number"},{"name":"ticketId","desc":"","lua_type":"string"},{"name":"previous","desc":"","lua_type":"number?\\n"}],"returns":[{"desc":"","lua_type":"Descriptor\\n"}],"function_type":"static","source":{"line":131,"path":"src/internal/Lanes.luau"}},{"name":"allFor","desc":"Every lane in a partition at `count`.","params":[{"name":"settings","desc":"","lua_type":"any"},{"name":"partition","desc":"","lua_type":"string"},{"name":"count","desc":"","lua_type":"number"},{"name":"previous","desc":"","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"{ Descriptor }\\n"}],"function_type":"static","source":{"line":146,"path":"src/internal/Lanes.luau"}},{"name":"clamp","desc":"Rounds to the nearest power of two within `[min, max]`. Counts must be powers\\nof two for [Lanes.legacyMaps] to be exact.","params":[{"name":"count","desc":"","lua_type":"number"},{"name":"min","desc":"","lua_type":"number"},{"name":"max","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":160,"path":"src/internal/Lanes.luau"}},{"name":"isPowerOfTwo","desc":"","params":[{"name":"count","desc":"","lua_type":"any"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":171,"path":"src/internal/Lanes.luau"}}],"properties":[],"types":[],"name":"Lanes","desc":"Key layout for the queue index.\\n\\nA queue is split into `partition` values (whatever `partitionKey` returns,\\nor `\\"all\\"`), and each partition into some number of lanes. A ticket is hashed\\ninto exactly one lane and is matched against the other tickets in it.\\n\\n**Lanes buy parallelism by splitting the pool.** One lane means one worker\\nsees every queued ticket and matches on its first scan; four lanes means four\\nservers can match simultaneously, each seeing a quarter of the queue. That\\ntrade only pays once a single lane is deep enough to fill matches on its own\\n\u2014 a two-player queue split across 64 lanes would leave its two players in\\ndifferent lanes, never matching.\\n\\nBecause the right number depends on live queue depth, [LaneScaler] adjusts it\\nat runtime and the count is **stamped into every key**:\\n\\n```\\nmu1:ranked:idx:EMEA:n04:02\\n                     ^^^ ^^\\n                   count lane\\n```\\n\\nThat stamp is what makes changing the count safe. Two servers that disagree\\nabout the count are not fighting over one key space; they are reading and\\nwriting different ones, and every ticket stays exactly where its writer put\\nit. Nothing is ever stranded by a resize \u2014 the worst case is that two pools\\nbriefly do not see each other, which `legacyMaps` closes.\\n\\nSort keys are queue timestamps, so an ascending range read is oldest-first\\nand matching is fair by default.","source":{"line":37,"path":"src/internal/Lanes.luau"}}')}}]);